"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["16758"],{87743(e){e.exports=JSON.parse('{"id":"F357","slug":"duration-gap","name":"Duration Gap and Equity Sensitivity","subject":"Banking & Financial Institutions","section":"Banking","topic":"Asset-liability management","level":"Intermediate","aliases":["asset liability management","ALM","interest rate risk of a bank","DGAP"],"formula":{"latex":"DGAP=D_{A}-\\\\frac{L}{A}D_{L},\\\\quad \\\\Delta E\\\\approx-DGAP\\\\times A\\\\times\\\\frac{\\\\Delta y}{1+y}","also":[],"text":"Duration gap = duration of assets - (liabilities / assets) x duration of liabilities; Change in equity value = - duration gap x assets x (change in yield) / (1 + yield)"},"symbols":[{"symbol":"D_A, D_L","meaning":"Duration of assets and of liabilities, in years","unit":"years"},{"symbol":"A, L","meaning":"Market value of assets and liabilities","unit":"money"},{"symbol":"Delta y","meaning":"Change in the general level of yields","unit":"percent"},{"symbol":"DGAP","meaning":"Duration gap: positive means assets are more rate-sensitive than funding","unit":"years"}],"when_to_use":"Use it to see how a rise in rates changes a bank\'s equity. A bank that funds long assets with short deposits has a positive duration gap, so higher rates cut asset values by more than they cut liabilities and equity falls. It shows value risk, whereas the repricing gap shows effects on income. It assumes a parallel yield shift and uses approximations that are less accurate for large moves.","worked_example":{"problem":"Assets are 8,000 with a duration of 4.5 years, liabilities 7,600 with a duration of 2.0 years. Yields are 5% and rise by 1 percentage point.","inputs":{"da":4.5,"dl":2,"a":8000,"l":7600,"y":5,"dy":1},"steps":[{"label":"Duration gap = D_A - (L / A) x D_L","working":"4.5-(7600 / 8000) x 2","value":"2.600"},{"label":"Change in equity = -gap x A x dy / (1 + y)","working":"-2.6 x 8000 x 0.01 / (1+0.05)","value":"-198.10"},{"label":"Equity = A - L","working":"8000-7600","value":"400.00"},{"label":"Change as a share of equity","working":"-198.095 / 400","value":"-49.5%"},{"label":"Liability duration that gives zero gap = D_A x A / L","working":"4.5 x 8000 / 7600","value":"4.74"}],"answer":"The duration gap is 2.600 years. A 1 point rise in yields lowers equity value by -198.10, which is -49.5% of the book equity of 400.00. To fully immunize, liability duration would need to be 4.74 years."},"calculator":{"available":true,"inputs":[{"id":"da","label":"Duration of assets","unit":"years","type":"number","default":4.5,"hint":""},{"id":"dl","label":"Duration of liabilities","unit":"years","type":"number","default":2,"hint":""},{"id":"a","label":"Assets","unit":"money","type":"number","default":8000,"hint":""},{"id":"l","label":"Liabilities","unit":"money","type":"number","default":7600,"hint":""},{"id":"y","label":"Yield level","unit":"%","type":"number","default":5,"hint":""},{"id":"dy","label":"Change in yield","unit":"%","type":"number","default":1,"hint":""}],"checks":[{"expr":"a>l and l>0","message":"Assets must exceed liabilities, which must be above zero."}],"steps":[{"id":"dg","label":"Duration gap = D_A - (L / A) x D_L","expr":"da-(l/a)*dl","format":"num3"},{"id":"de","label":"Change in equity = -gap x A x dy / (1 + y)","expr":"-dg*a*dy/(1+y)","format":"money"},{"id":"eq","label":"Equity = A - L","expr":"a-l","format":"money"},{"id":"pe","label":"Change as a share of equity","expr":"de/eq","format":"pct1"},{"id":"dlstar","label":"Liability duration that gives zero gap = D_A x A / L","expr":"da*a/l","format":"num2"}],"results":["dg","de","pe","dlstar"],"percent_inputs_typed_as_whole_numbers":true,"tested_against":{"dg":2.6,"de":-198.09523809523807,"eq":400,"pe":-0.4952380952380952,"dlstar":4.7368421052631575}},"finder":{"finds":"A bank\'s equity risk from a parallel rate move","needs":"Durations, asset and liability values, yield change"},"related":[{"slug":"repricing-gap","name":"Repricing Gap and Net Interest Income"},{"slug":"irrbb-eve-nii","name":"Banking Book Interest Rate Risk: EVE and NII"},{"slug":"duration","name":"Macaulay and Modified Duration"}],"related_ids":["F358","F391","F288"],"group":"Money, banks and the economy","mathml":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\" display=\\"block\\"><semantics><mrow><mi>D</mi><mi>G</mi><mi>A</mi><mi>P</mi><mo>=</mo><msub><mi>D</mi><mi>A</mi></msub><mo>\u2212</mo><mfrac><mi>L</mi><mi>A</mi></mfrac><msub><mi>D</mi><mi>L</mi></msub><mo separator=\\"true\\">,</mo><mspace width=\\"1em\\"/><mi mathvariant=\\"normal\\">\u0394</mi><mi>E</mi><mo>\u2248</mo><mo>\u2212</mo><mi>D</mi><mi>G</mi><mi>A</mi><mi>P</mi><mo>\xd7</mo><mi>A</mi><mo>\xd7</mo><mfrac><mrow><mi mathvariant=\\"normal\\">\u0394</mi><mi>y</mi></mrow><mrow><mn>1</mn><mo>+</mo><mi>y</mi></mrow></mfrac></mrow><annotation encoding=\\"application/x-tex\\">DGAP=D_{A}-\\\\frac{L}{A}D_{L},\\\\quad \\\\Delta E\\\\approx-DGAP\\\\times A\\\\times\\\\frac{\\\\Delta y}{1+y}</annotation></semantics></math></span>","alsoMathml":[],"prev":{"slug":"dupont-analysis","name":"DuPont Analysis (3-Step and 5-Step)"},"next":{"slug":"dv01","name":"DV01 (Dollar Value of a Basis Point)"},"lesson":null,"total":522}')}}]);